110	    // "{{result/<pointer>}}" is the last tool result in this request;
111	    // "{{workspace/sessionId}}", "{{workspace/revision}}",
112	    // "{{workspace/activePlateId}}", "{{workspace/firstObjectId}}" (the
113	    // active plate's first object), "{{workspace/filamentPreset}}" and
114	    // "{{workspace/printerPreset}}" the project now; "{{object}}" the object
115	    // an "eachObject" answer is being read for.
116	    nlohmann::json prompt_fill(const nlohmann::json& value, const nlohmann::json& body, const std::string& name)
117	    {
118	        using nlohmann::json;
119	        if (value.is_object() || value.is_array()) {
120	            json filled = value;
121	            for (auto& [key, item] : filled.items())
122	                item = prompt_fill(item, body, name);
123	            return filled;
124	        }
125	        if (!value.is_string())
126	            return value;
127	        const std::string text = value;
128	        if (text.size() < 5 || text.rfind("{{", 0) != 0 || text.compare(text.size() - 2, 2, "}}") != 0)
129	            return value;
130	        const std::string path = text.substr(2, text.size() - 4);
131	        if (path == "object" && !m_prompt_object.empty())
132	            return m_prompt_object;
133	        if (path == "workspace/sessionId")
134	            return std::to_string(installed_shell()->workspace()->snapshot().session.value());
135	        if (path == "workspace/revision")
136	            return installed_shell()->workspace()->snapshot().revision;
137	        if (path == "workspace/filamentPreset")
138	            return installed_shell()->workspace()->snapshot().setup.filament_preset;
139	        if (path == "workspace/printerPreset")
140	            return installed_shell()->workspace()->snapshot().setup.printer_preset;
141	        if (path == "workspace/activePlateId" || path == "workspace/firstObjectId")
142	            for (const auto& plate : installed_shell()->workspace()->snapshot().plates)
143	                if (plate.active && (path == "workspace/activePlateId" || !plate.objects.empty()))
144	                    return std::to_string(path == "workspace/activePlateId" ? plate.id.value() : plate.objects.front().id.value());
145	        if (path.rfind("result/", 0) == 0) {
146	            const json& input = body.at("input");
147	            for (auto item = input.rbegin(); item != input.rend(); ++item)
148	                if (item->value("type", "") == "function_call_output") {
149	                    const json output = json::parse(item->at("output").get<std::string>());
150	                    const json::json_pointer pointer(path.substr(6));
151	                    if (output.contains("result") && output["result"].contains(pointer))
152	                        return output["result"][pointer];
153	                    break;
154	                }
155	        }
156	        check(false, name + "_fills " + text);
157	        return value;
158	    }
