160	    // Answers a held request with model output, as the service streams it.
161	    static void prompt_answer(HeldModelRequest& request, const nlohmann::json& output, const std::string& text)
162	    {
163	        using Event = Agent::AgentHttpEvent;
164	        const auto frame = [](const nlohmann::json& event) { return "event: message\ndata: " + event.dump() + "\n\n"; };
165	        if (!text.empty())
166	            request.answer(Event{Event::Kind::Data, frame({{"type", "response.output_text.delta"}, {"delta", text}}), {}, 0});
167	        request.answer(Event{Event::Kind::Data,
168	                             frame({{"type", "response.completed"}, {"response", {{"output", output}}}}), {}, 0});
169	        request.answer(Event{Event::Kind::Complete, {}, {}, 200});
170	    }
