172	    // The next request of this turn the model is asked, past any chat title.
173	    std::optional<HeldModelRequest> prompt_next_request()
174	    {
175	        for (;;) {
176	            if (!wait_for([] { return !g_held_model_requests.empty(); }, std::chrono::seconds(120)))
177	                return std::nullopt;
178	            HeldModelRequest request = std::move(g_held_model_requests.front());
179	            g_held_model_requests.pop_front();
180	            if (request.body.contains("tools"))
181	                return request;
182	            prompt_answer(request, nlohmann::json::array({{{"type", "message"}, {"role", "assistant"},
183	                                                           {"content", nlohmann::json::array({{{"type", "output_text"},
184	                                                                                               {"text", "Fixture chat"}}})}}}),
185	                          "Fixture chat");
186	        }
187	    }
