189	    std::string m_prompt_object;  // for "{{object}}"
190	
191	    // The answers' reads called after the kept request, in the same turn;
192	    // returns each with the result the app gave, as the model would read it.
193	    // A read marked "eachObject" is called once for every object on every
194	    // plate, and an "allSettings" entry with it once for every object.
195	    // An "allSettings" entry reads every setting of its scope:
196	    // the keys come from the app's own settings_search (an empty query lists
197	    // them all, page by page; those pages are not kept), then settings_get
198	    // reads them 32 at a time. With "keysOf" it reads, under its scope, the
199	    // keys of the scopes named, read before it, that are not its own: how
200	    // the app answers a name asked for under the wrong scope. The workspace block every result
201	    // carries is kept once, beside them, and left out of each result that
202	    // repeats it exactly.
203	    nlohmann::json prompt_answers(const std::string& name, HeldModelRequest request, const nlohmann::json& script_reads)
204	    {
205	        using nlohmann::json;
206	        json answers = json::array();
207	        int  calls   = 0;
208	        // One read in the turn; the result as the app gave it, or nothing.
209	        const auto call = [&](const std::string& tool, const json& arguments) -> std::optional<std::string> {
210	            const std::string call_id = "call_" + name + "_answer_" + std::to_string(++calls);
211	            prompt_answer(request, json::array({{{"type", "function_call"}, {"call_id", call_id}, {"name", tool},
212	                                                 {"arguments", arguments.dump()}}}), "");
213	            std::optional<HeldModelRequest> next = prompt_next_request();
214	            check(next.has_value(), name + "_answer_" + tool + "_returned");
215	            if (!next)
216	                return std::nullopt;
217	            request = std::move(*next);
218	            const std::string output = request.body.at("input").back().at("output");
219	            const bool succeeded = json::parse(output).value("state", "") == "succeeded";
220	            check(succeeded, name + "_answer_" + tool + "_succeeded");
221	            return succeeded ? std::optional<std::string>(output) : std::nullopt;
222	        };
223	        std::map<std::string, std::vector<std::string>> scope_keys;
224	        bool ok = true;
225	        for (const json& read : script_reads) {
226	            if (!ok)
227	                break;
228	            std::vector<std::string> objects{std::string()};
229	            if (read.value("eachObject", false)) {
230	                objects.clear();
231	                for (const auto& plate : installed_shell()->workspace()->snapshot().plates)
232	                    for (const auto& object : plate.objects)
233	                        objects.push_back(std::to_string(object.id.value()));
234	            }
235	            if (read.contains("allSettings")) {
236	                const std::string scope = read["allSettings"];
237	                for (const std::string& object : objects) {
238	                    if (!ok)
239	                        break;
240	                    m_prompt_object = object;
241	                    const json target = prompt_fill(read.value("target", json()), request.body, name);
242	                    std::vector<std::string> keys;
243	                    if (read.contains("keysOf")) {
244	                        const auto& own = scope_keys[scope];
245	                        for (const json& other : read["keysOf"])
246	                            for (const std::string& key : scope_keys[other.get<std::string>()])
247	                                if (std::find(own.begin(), own.end(), key) == own.end())
248	                                    keys.push_back(key);
249	                    } else if (scope_keys.count(scope)) {
250	                        keys = scope_keys[scope];  // every object of the scope has the same settings
251	                    } else {
252	                        std::string cursor;
253	                        do {
254	                            json search{{"scope", scope}, {"query", ""}, {"limit", 25}};
255	                            if (!target.is_null())
256	                                search["target"] = target;
257	                            if (!cursor.empty())
258	                                search["cursor"] = cursor;
259	                            const std::optional<std::string> page = call("settings_search", search);
260	                            if (!(ok = page.has_value()))
261	                                break;
262	                            const json result = json::parse(*page).at("result");
263	                            for (const json& item : result.at("items"))
264	                                keys.push_back(item.at("key"));
265	                            cursor = result.value("nextCursor", "");
266	                        } while (!cursor.empty());
267	                        scope_keys[scope] = keys;
268	                    }
269	                    for (std::size_t first = 0; ok && first < keys.size(); first += 32) {
270	                        json arguments{{"scope", scope},
271	                                       {"keys", std::vector<std::string>(keys.begin() + first, keys.begin() + std::min(keys.size(), first + 32))}};
272	                        if (!target.is_null())
273	                            arguments["target"] = target;
274	                        const std::optional<std::string> output = call("settings_get", arguments);
275	                        if ((ok = output.has_value()))
276	                            answers.push_back({{"tool", "settings_get"}, {"arguments", arguments}, {"output", *output}});
277	                    }
278	                    std::cerr << "HARNESS PROMPT " << name << " allSettings " << scope << (object.empty() ? "" : " " + object)
279	                              << (read.contains("keysOf") ? " (other scopes' keys)" : "") << " keys=" << keys.size() << '\n';
280	                }
281	                continue;
282	            }
283	            for (const std::string& object : objects) {
284	                m_prompt_object = object;
285	                const json arguments = prompt_fill(read.value("arguments", json::object()), request.body, name);
286	                const std::optional<std::string> output = call(read.at("call"), arguments);
287	                if (!(ok = output.has_value()))
288	                    break;
289	                answers.push_back({{"tool", read.at("call")}, {"arguments", arguments}, {"output", *output}});
290	            }
291	        }
292	        m_prompt_object.clear();
293	        prompt_answer(request, json::array(), "");
294	        wait_for([this] { return !g_held_model_requests.empty() || !project_host().busy(); }, std::chrono::seconds(10));
295	        json shared = json::object();
296	        for (json& answer : answers) {
297	            json output = json::parse(answer["output"].get<std::string>());
298	            const json block{{"workspace", output.value("workspace", json())}, {"workspaceRevision", output.value("workspaceRevision", json())}};
299	            if (shared.empty())
300	                shared = block;
301	            if (block != shared)
302	                continue;
303	            output.erase("workspace");
304	            output.erase("workspaceRevision");
305	            answer["output"] = output.dump();
306	            answer["sharedWorkspace"] = true;
307	        }
308	        return {{"reads", answers}, {"shared", shared}};
309	    }
