311	    // One step of a conversation: what the person does, then the model's
312	    // scripted outputs, one per request the app sends, until they run out.
313	    // The record point numbered `target` is kept, with its answers, and ends
314	    // the conversation (2); otherwise 1, or 0 on a failure.
315	    int prompt_step(const std::string& name, const nlohmann::json& step, nlohmann::json& recorded,
316	                    const nlohmann::json& tools, const std::string& instructions, const nlohmann::json& reads,
317	                    int& point, int target)
318	    {
319	        using nlohmann::json;
320	        using namespace std::chrono_literals;
321	        Agent::AgentHost& host = project_host();
322	        const json        scripted = step.value("replies", json::array());
323	        std::deque<json>  replies(scripted.begin(), scripted.end());
324	
325	        if (step.contains("say")) {
326	            static int next = 0;
327	            ++next;
328	            host.on_page_message(json{{"protocol", Agent::Protocol::kName},
329	                                      {"version", Agent::Protocol::kVersion},
330	                                      {"id", "prompt-" + std::to_string(next)},
331	                                      {"type", Agent::Protocol::kUserMessage},
332	                                      {"payload", {{"clientMessageId", "prompt-c-" + std::to_string(next)}, {"text", step["say"]}}}}
333	                                     .dump());
334	        } else if (step.contains("issue")) {
335	            // A setting typed in by hand, the issue OrcaSlicer reports for
336	            // it, and a press of one of the issue's two buttons.
337	            prompt_hand_edit(step.at("set"));
338	            const std::string setting = step.at("set").begin().key();
339	            std::string       issue_id;
340	            wait_for([&] {
341	                issue_monitor().refresh_now();
342	                for (const auto& issue : issues().issues)
343	                    if (issues().checked && issue.source == PrintIssues::IssueSource::Validation && issue.setting == setting)
344	                        issue_id = issue.id;
345	                return !issue_id.empty();
346	            }, 30s);
347	            check(!issue_id.empty(), name + "_issue_reported");
348	            const std::string outcome = issue_id.empty() ? "" : installed_shell()->submit_issue(issue_id, step["issue"]).outcome;
349	            std::cerr << "HARNESS PROMPT " << name << " issue " << issue_id << " outcome=" << outcome << '\n';
350	            check(outcome == "started", name + "_issue_sent_to_the_chat");
351	        } else if (step.contains("open")) {
352	            // A project someone saved with an author note in its description,
353	            // written by the app's own exporter, then opened.
354	            if (!m_plater->model().model_info)
355	                m_plater->model().model_info = std::make_shared<ModelInfo>();
356	            m_plater->model().model_info->description = step.value("description", "");
357	            const fs::path file = fs::path(data_dir()) / (step["open"].get<std::string>() + ".3mf");
358	            check(m_plater->export_3mf(file, SaveStrategy::SplitModel | SaveStrategy::ShareMesh | SaveStrategy::Silence) >= 0,
359	                  name + "_project_saved");
360	            check(m_plater->new_project(true, true) != wxID_CANCEL, name + "_saved_project_closed");
361	            m_plater->load_project(from_u8(file.string()), "-");
362	        }
363	
364	        bool expect_failure = false;
365	        int  calls          = 0;
366	        for (;;) {
367	            // The chat title is asked for after a reply ends; no case reads it.
368	            wait_for([&] { return !g_held_model_requests.empty() || (replies.empty() && !host.busy()); }, 120s);
369	            if (g_held_model_requests.empty()) {
370	                if (!replies.empty()) {
371	                    const auto snapshot = installed_shell()->workspace()->snapshot();
372	                    std::cerr << "HARNESS PROMPT " << name << " waiting: slicing.running=" << snapshot.slicing.running
373	                              << " orca_slicing=" << m_plater->is_background_process_slicing();
374	                    for (const auto& plate : snapshot.plates)
375	                        std::cerr << " plate " << plate.id.value() << " active=" << plate.active << " sliced=" << plate.sliced;
376	                    issue_monitor().refresh_now();
377	                    for (const auto& issue : issues().issues)
378	                        std::cerr << " | issue " << issue.id << " '" << issue.message << "'";
379	                    for (const auto& activity : host.tools().activities())
380	                        std::cerr << " | " << activity.tool << '=' << Agent::tool_state_name(activity.state);
381	                    std::cerr << '\n';
382	                }
383	                break;
384	            }
385	            HeldModelRequest request = std::move(g_held_model_requests.front());
386	            g_held_model_requests.pop_front();
387	            if (!request.body.contains("tools")) {
388	                prompt_answer(request, json::array({{{"type", "message"}, {"role", "assistant"},
389	                                                     {"content", json::array({{{"type", "output_text"}, {"text", "Fixture chat"}}})}}}),
390	                              "Fixture chat");
391	                continue;
392	            }
393	            const json& input = request.body.at("input");
394	            if (!input.empty() && input.back().value("type", "") == "function_call_output") {
395	                const json output = json::parse(input.back().at("output").get<std::string>());
396	                const std::string state = output.value("state", "");
397	                std::cerr << "HARNESS PROMPT " << name << " result state=" << state
398	                          << (output.contains("error") ? " error=" + output["error"].value("code", "") : std::string()) << '\n';
399	                check((state == "failed") == expect_failure && state != "running", name + "_call_" + std::to_string(calls) + "_outcome");
400	            }
401	            if (replies.empty()) {
402	                check(false, name + "_unscripted_request");
403	                prompt_answer(request, json::array(), "");
404	                continue;
405	            }
406	            const json reply = replies.front();
407	            replies.pop_front();
408	            if (reply.contains("set"))
