        for a in c["answers"]:
            o = json.loads(a["output"])
            if a.pop("settingItems", False):
                for f in ("items", "unknownKeys"):
                    if f in o["result"]:
                        o["result"][f] = [d["settingItems"][i] for i in o["result"][f]]
            if a.pop("sharedWorkspace", False):
                o.update(c["sharedWorkspace"])
            a["output"] = o
        c.pop("sharedWorkspace")
        for it in c["body"]["input"]:
            if "output" in it:
                it["output"] = json.loads(it["output"])
        out[name] = c
    return out
def norm(x):
    s = json.dumps(x, sort_keys=True, ensure_ascii=False)
    s = re.sub(r'\\"(\d+)\\"', '"N"', s)
    s = re.sub(r'"\d+"', '"N"', s)
    s = re.sub(r'"(revision|workspaceRevision|version)": \d+', r'"\1": 0', s)
    s = re.sub(r'\\"(revision|workspaceRevision)\\":\d+', r'"\1":0', s)
    s = re.sub(r'"t-\d+"', '"t-N"', s)
    s = re.sub(r'\d{4}-\d\d-\d\dT[\d:.]+Z?', 'TIME', s)
    s = re.sub(r'/(private/)?var/folders/[^"\\ ]+', 'TMP', s)
    s = re.sub(r'jusprin-shell-[\w-]+', 'TMP', s)
    return s
a, b = load(sys.argv[1]), load(sys.argv[2])
