        i = next(i for i, (x, y) in enumerate(zip(na, nb)) if x != y) if len(na) == len(nb) or True else 0
        print("DIFF", name, len(na), len(nb), "|", na[max(0,i-150):i+150], "\n   vs", nb[max(0,i-150):i+150])
